Import-Module ActiveDirectory; $csvPath = "C:\ADImport\employees.csv"; $logPath = "C:\ADImport\temp_passwords.txt"; $users = Import-Csv -Path $csvPath; foreach ($user in $users) { Add-Type -AssemblyName System.Web; $tempPassword = [System.Web.Security.Membership]::GeneratePassword(12, 2); $securePassword = ConvertTo-SecureString $tempPassword -AsPlainText -Force; $targetOU = $user.OU; if ($user.Department -eq "HR") { $targetOU = "OU=HR Department,DC=corp,DC=local" }; $userParams = @{ GivenName = $user.FirstName; Surname = $user.LastName; Name = "$($user.FirstName) $($user.LastName)"; SamAccountName = $user.SamAccountName; UserPrincipalName = $user.UserPrincipalName; Department = $user.Department; Title = $user.Title; Path = $targetOU; AccountPassword = $securePassword; ChangePasswordAtLogon = $true; Enabled = $true }; try { if (Get-ADUser -Filter "SamAccountName -eq '$($user.SamAccountName)'") { Write-Warning "User $($user.SamAccountName) already exists." } else { New-ADUser @userParams; Write-Host "Created: $($user.SamAccountName)" -ForegroundColor Green } } catch { Write-Error "Failed: $($user.SamAccountName)" } }
